java('evaluation','RelevanceEvaluator',r'''import java.io.*;
import java.nio.charset.StandardCharsets;
import java.nio.file.*;
import java.util.*;
public final class RelevanceEvaluator {
 private RelevanceEvaluator(){}
 public record Judged(String id,String split,String type,String text,Map<String,Integer> grades){}
 public static List<Judged> judgments(Path fixtures)throws IOException{List<Judged> out=new ArrayList<>();for(String line:Files.readAllLines(fixtures.resolve("judgments.tsv"))){String[] p=line.split("\t");Map<String,Integer> grades=new TreeMap<>();for(String item:p[4].split(",")){int at=item.lastIndexOf(':');grades.put(item.substring(0,at),Integer.parseInt(item.substring(at+1)));}out.add(new Judged(p[0],p[1],p[2],p[3],Map.copyOf(grades)));}if(out.size()!=80||out.stream().filter(q->q.split().equals("development")).count()!=40||out.stream().filter(q->q.split().equals("validation")).count()!=20||out.stream().filter(q->q.split().equals("held-out")).count()!=20)throw new IOException("evaluation split mismatch");return out;}
 public static void verifyFreeze(Path fixtures)throws IOException{for(String line:Files.readAllLines(fixtures.resolve("FREEZE.sha256"))){String[] p=line.split("  ");if(p.length!=2||!Digests.sha256(Files.readAllBytes(fixtures.resolve(p[1]))).equals(p[0]))throw new IOException("frozen corpus changed");}if(!Files.exists(fixtures.resolve("REVIEW-APPROVED.md")))throw new IOException("independent pre-measurement label review required");}
 public static void run(Path data,Path fixtures,Path output,String phase)throws IOException{verifyFreeze(fixtures);if(!Set.of("development","final").contains(phase))throw new IllegalArgumentException("evaluation phase");AuthorizationFilter auth=new AuthorizationFilter();var a=auth.update("evaluator","evaluation",Set.of("corpus"),true);List<Judged> queries=judgments(fixtures);try(SearchEngine engine=new SearchEngine(data,auth)){List<SnapshotManifest.Entry> entries=new ArrayList<>();for(String line:Files.readAllLines(fixtures.resolve("corpus.tsv"))){String[] p=line.split("\t",-1);byte[] content=Base64.getDecoder().decode(p[2]);List<String> symbols=Arrays.stream(p[1].split(" ")).limit(256).toList();entries.add(new SnapshotManifest.Entry(p[0],engine.contentStore().put(content),p[0].endsWith(".java")?"java":"text","source",symbols,"", ""));}engine.ingest(a,"corpus-"+Digests.sha256(Files.readAllBytes(fixtures.resolve("corpus.tsv"))),new SnapshotManifest("evaluation","corpus","frozen-v2",true,entries,Set.of()),GenerationBuilder.Fault.none(),()->false);Files.createDirectories(output);Map<String,Double> validationScores=new HashMap<>();StringBuilder rows=new StringBuilder("phase,mode,query,split,type,ndcg10,mrr10,recall20,returnedPaths\n");List<String> summary=new ArrayList<>();for(var mode:QueryPlanner.Mode.values()){for(String split:List.of("development","validation")){double ndcg=0,mrr=0,recall=0;int n=0;for(Judged q:queries)if(q.split().equals(split)){var response=engine.search(a.principal(),new SearchEngine.Request(q.text(),20,null,Map.of()),mode);List<String> paths=response.results().stream().map(SearchEngine.Hit::path).toList();var m=RelevanceMetrics.evaluate(paths,q.grades());ndcg+=m.ndcg10();mrr+=m.mrr10();recall+=m.recall20();n++;rows.append(phase).append(',').append(mode).append(',').append(q.id()).append(',').append(split).append(',').append(q.type()).append(',').append(m.ndcg10()).append(',').append(m.mrr10()).append(',').append(m.recall20()).append(',').append(String.join("|",paths)).append('\n');}summary.add(mode+" "+split+" nDCG10="+ndcg/n+" MRR10="+mrr/n+" Recall20="+recall/n);if(split.equals("validation"))validationScores.put(mode.name(),ndcg/n);}}String selected=validationScores.get("SOURCE_AWARE")>validationScores.get("BASELINE")?"SOURCE_AWARE":"BASELINE";Path selection=output.resolve("selection.txt");String decision="Pre-held-out selection from development/validation only: "+selected+"\n";if(phase.equals("development")){Files.writeString(selection,decision);summary.add("Held-out remains unopened.");}else{if(!Files.exists(selection)||!Files.readString(selection).equals(decision))throw new IOException("run development phase and freeze selection before held-out");for(var mode:QueryPlanner.Mode.values()){double ndcg=0,identifierMrr=0,recall=0;int n=0,ids=0;for(Judged q:queries)if(q.split().equals("held-out")){var response=engine.search(a.principal(),new SearchEngine.Request(q.text(),20,null,Map.of()),mode);List<String> paths=response.results().stream().map(SearchEngine.Hit::path).toList();var m=RelevanceMetrics.evaluate(paths,q.grades());ndcg+=m.ndcg10();recall+=m.recall20();n++;if(q.type().equals("identifier")){identifierMrr+=m.mrr10();ids++;}rows.append(phase).append(',').append(mode).append(',').append(q.id()).append(',').append(q.split()).append(',').append(q.type()).append(',').append(m.ndcg10()).append(',').append(m.mrr10()).append(',').append(m.recall20()).append(',').append(String.join("|",paths)).append('\n');}summary.add(mode+" held-out nDCG10="+ndcg/n+" identifierMRR10="+identifierMrr/ids+" Recall20="+recall/n+" targetPass="+(ndcg/n>=0.75&&identifierMrr/ids>=0.9));}}Files.writeString(output.resolve(phase+"-per-query.csv"),rows);Files.writeString(output.resolve(phase+"-summary.txt"),String.join("\n",summary)+"\n");System.out.println(String.join("\n",summary));}}
}
''')
java('evaluation','WorkloadGenerator','''import java.io.*;
import java.nio.charset.StandardCharsets;
import java.nio.file.*;
import java.util.*;
public final class WorkloadGenerator {
 public record Generated(long bytes,List<SnapshotManifest> manifests){}
 private WorkloadGenerator(){}
 public static Generated generate(ContentAddressedStore store,int documents,long seed)throws IOException{if(documents<3||documents>100_000)throw new IllegalArgumentException("workload size");List<SnapshotManifest> manifests=new ArrayList<>();long bytes=0;Random random=new Random(seed);for(int tenant=0;tenant<3;tenant++){List<SnapshotManifest.Entry> entries=new ArrayList<>();for(int i=tenant;i<documents;i+=3){String symbol="resolveGeneration"+i;String text="/** Source snapshot atomic publication reader lease repository authorization. */\\npublic class Component"+i+" { public long "+symbol+"(long prior) { long revision = "+random.nextInt(1_000_000)+"L; return Math.max(prior, revision); } }\\n";byte[] b=text.getBytes(StandardCharsets.UTF_8);bytes+=b.length;entries.add(new SnapshotManifest.Entry("src/Component"+i+".java",store.put(b),"java","source",List.of(symbol,"Component"+i),"io.demo:component"+i,"1.0"));}manifests.add(new SnapshotManifest("tenant"+tenant,"public","seed-"+seed,true,entries,Set.of()));}return new Generated(bytes,List.copyOf(manifests));}
}
''')
java('evaluation','RelevanceMetricsTest','''import static org.junit.jupiter.api.Assertions.*;
import java.util.*;
import org.junit.jupiter.api.Test;
class RelevanceMetricsTest {
 @Test void independentHandCalculatedGradedMetrics(){Map<String,Integer> grades=Map.of("a",3,"b",2,"c",1);var perfect=RelevanceMetrics.evaluate(List.of("a","b","c"),grades);assertEquals(1,perfect.ndcg10(),1e-12);assertEquals(1,perfect.mrr10(),1e-12);assertEquals(1,perfect.recall20(),1e-12);var second=RelevanceMetrics.evaluate(List.of("irrelevant","b"),grades);double gain=3/(Math.log(3)/Math.log(2));double ideal=7+3/(Math.log(3)/Math.log(2))+1/(Math.log(4)/Math.log(2));assertEquals(gain/ideal,second.ndcg10(),1e-12);assertEquals(0.5,second.mrr10());assertEquals(1.0/3,second.recall20(),1e-12);var empty=RelevanceMetrics.evaluate(List.of(),Map.of());assertEquals(new RelevanceMetrics.Values(0,0,0),empty);assertThrows(IllegalArgumentException.class,()->RelevanceMetrics.evaluate(List.of("a","a"),grades));assertThrows(IllegalArgumentException.class,()->RelevanceMetrics.evaluate(List.of("a"),Map.of("a",4)));}
 @Test void cutoffBoundariesAreIndependent(){List<String> values=new ArrayList<>();for(int i=0;i<20;i++)values.add("miss"+i);values.add("a");var zero=RelevanceMetrics.evaluate(values,Map.of("a",3));assertEquals(new RelevanceMetrics.Values(0,0,0),zero);values.set(19,"a");values.removeLast();var last=RelevanceMetrics.evaluate(values,Map.of("a",3));assertEquals(0,last.ndcg10());assertEquals(0,last.mrr10());assertEquals(1,last.recall20());}
}
''',True)
